class BenefitApplicationOutcome(str, Enum):
    CONFIRMED = "CONFIRMED"
    REJECTED = "REJECTED"
    FAILED = "FAILED"


@dataclass(frozen=True)
class BenefitApplicationCorrelation:
    application_id: str
    source_system: str
    source_transaction_id: str
    policy_id: str
    policy_version: str
    contract_id: str
    unit_id: str


@dataclass(frozen=True)
class BenefitProviderResult:
    application_id: str
    outcome: BenefitApplicationOutcome
    provider_reference: Optional[str]
    evidence_reference: Optional[str]
    message: Optional[str] = None


def benefit_application_idempotency_key(correlation: BenefitApplicationCorrelation) -> str:
    required = [
        correlation.application_id,
        correlation.source_system,
        correlation.source_transaction_id,
        correlation.policy_id,
        correlation.policy_version,
        correlation.contract_id,
        correlation.unit_id,
    ]
    if any(not str(value or "").strip() for value in required):
        raise ValueError("La correlacion de beneficio requiere identificadores estables completos")
    return "|".join(str(value).strip() for value in required)


def validate_benefit_provider_result(result: BenefitProviderResult) -> None:
    if not str(result.application_id or "").strip():
        raise ValueError("BenefitProviderResult requiere application_id")
    if result.outcome == BenefitApplicationOutcome.CONFIRMED:
        if not str(result.provider_reference or "").strip():
            raise ValueError("CONFIRMED requiere provider_reference")
        if not str(result.evidence_reference or "").strip():
            raise ValueError("CONFIRMED requiere evidence_reference")
    if result.outcome in {BenefitApplicationOutcome.REJECTED, BenefitApplicationOutcome.FAILED}:
        if not str(result.message or "").strip():
            raise ValueError("REJECTED/FAILED requiere message auditable")


def should_send_benefit_application(*, current_status: str, same_idempotency_key: bool) -> bool:
    normalized = str(current_status or "").strip().upper()
    if same_idempotency_key and normalized == "CONFIRMED":
        return False
    if same_idempotency_key and normalized == "SENT_TO_PROVIDER":
        return False
    return True


def derive_benefit_application_status(result: BenefitProviderResult) -> str:
    validate_benefit_provider_result(result)
    return result.outcome.value


def confirmed_benefit_is_economic_terminal_state() -> bool:
    return True

import pytest

from modules.cava_socios.domain import (
    BenefitApplicationCorrelation,
    BenefitApplicationOutcome,
    BenefitProviderResult,
    benefit_application_idempotency_key,
    confirmed_benefit_is_economic_terminal_state,
    derive_benefit_application_status,
    should_send_benefit_application,
    validate_benefit_provider_result,
)


def _correlation(**overrides):
    data = dict(
        application_id="APP-1",
        source_system="POS-CANONICAL",
        source_transaction_id="TX-1",
        policy_id="POL-1",
        policy_version="V3",
        contract_id="CTR-1",
        unit_id="UNIT-1",
    )
    data.update(overrides)
    return BenefitApplicationCorrelation(**data)


def test_idempotency_key_is_stable_for_same_application_context():
    assert benefit_application_idempotency_key(_correlation()) == benefit_application_idempotency_key(_correlation())


def test_idempotency_key_changes_when_source_transaction_changes():
    assert benefit_application_idempotency_key(_correlation()) != benefit_application_idempotency_key(_correlation(source_transaction_id="TX-2"))


def test_confirmed_same_key_is_not_sent_again():
    assert should_send_benefit_application(current_status="CONFIRMED", same_idempotency_key=True) is False


def test_inflight_same_key_is_not_sent_again():
    assert should_send_benefit_application(current_status="SENT_TO_PROVIDER", same_idempotency_key=True) is False


def test_failed_same_key_can_be_retried_under_orchestrator_control():
    assert should_send_benefit_application(current_status="FAILED", same_idempotency_key=True) is True


def test_confirmed_requires_provider_and_evidence_references():
    with pytest.raises(ValueError):
        validate_benefit_provider_result(BenefitProviderResult(
            application_id="APP-1", outcome=BenefitApplicationOutcome.CONFIRMED,
            provider_reference=None, evidence_reference=None,
        ))
    result = BenefitProviderResult(
        application_id="APP-1", outcome=BenefitApplicationOutcome.CONFIRMED,
        provider_reference="POS-REF-1", evidence_reference="EVID-1",
    )
    validate_benefit_provider_result(result)
    assert derive_benefit_application_status(result) == "CONFIRMED"


def test_rejected_or_failed_requires_auditable_message():
    with pytest.raises(ValueError):
        validate_benefit_provider_result(BenefitProviderResult(
            application_id="APP-1", outcome=BenefitApplicationOutcome.REJECTED,
            provider_reference=None, evidence_reference=None, message=None,
        ))


def test_confirmed_is_terminal_for_economic_effect():
    assert confirmed_benefit_is_economic_terminal_state() is True
